export function validateForm(values) {
  const errors = {};

  if (values.name === undefined || values.name.trim() === '') {
    errors.name = 'Name is required';
  }

  if (values.email === undefined || !values.email.includes('@')) {
    errors.email = 'Email is invalid';
  }

  return errors;
}

